using System.Text.Json.Nodes;

namespace Jindan.Modules.ReportStudio;

public sealed partial class ReportDocument
{
    private static readonly (string Id, string Title)[] ElectricalGroups = [("kepco", "최근3개년 한전 사용정보"), ("thermal", "열화상 측정"), ("quality", "전력품질 측정"), ("insulation", "절연저항 직접 측정"), ("current", "운전전류 직접 측정"), ("equipment", "전기기기·계측기 목록/점검"), ("management", "일반 관리요령"), ("improvement", "금회 개선사항 협의")];
    private readonly DataGridView _electricalGrid = new() { Name = "ElectricalGroups", Dock = DockStyle.Fill, AllowUserToAddRows = false, RowHeadersVisible = false, AutoGenerateColumns = false, SelectionMode = DataGridViewSelectionMode.FullRowSelect };
    private readonly DataGridView _thermalGrid = new() { Name = "ThermalDeliveries", Dock = DockStyle.Fill, AllowUserToAddRows = false, RowHeadersVisible = false, AutoGenerateColumns = false };
    private readonly TextBox _electricalScope = new() { Name = "ElectricalScope", Width = 220, PlaceholderText = "대상 시설·설비 범위", MaxLength = 500 };
    private readonly ComboBox _kepcoMode = new() { Name = "KepcoMode", DropDownStyle = ComboBoxStyle.DropDownList, Width = 110 };
    private readonly TextBox _kepcoReason = new() { Name = "KepcoReason", Width = 220, PlaceholderText = "포함/제외 근거", MaxLength = 1000 };
    private readonly TextBox _periodStart = new() { Name = "KepcoPeriodStart", Width = 100, PlaceholderText = "YYYY-MM-DD" };
    private readonly TextBox _periodEnd = new() { Name = "KepcoPeriodEnd", Width = 100, PlaceholderText = "YYYY-MM-DD" };
    private readonly RichTextBox _electricalResult = new() { Name = "ElectricalPreparationResult", Dock = DockStyle.Fill, ReadOnly = true };
    private JsonObject _electricalState = new();

    private void BuildElectricalTab()
    {
        var tab = new TabPage("전기 자료·열화상 연결") { Name = "ElectricalPreparationTab" }; var toolbar = new FlowLayoutPanel { Dock = DockStyle.Top, AutoSize = true }; toolbar.Controls.AddRange([_electricalScope, _kepcoMode, _kepcoReason, _periodStart, _periodEnd]); _kepcoMode.Items.AddRange(["auto", "include", "exclude"]); _kepcoMode.SelectedItem = "auto";
        foreach (var (name, label, action) in new (string, string, Func<Task>)[] { ("ElectricalInspect", "원문 항목·연결 검사", InspectElectricalAsync), ("ElectricalLink", "선택 자료를 선택 분야에 연결", LinkSelectedElectricalAsync), ("ElectricalUnlink", "선택 분야 자료 연결 해제", UnlinkElectricalAsync), ("ElectricalSave", "범위·조건·협의 저장", SaveElectricalAsync), ("ThermalAdd", "열화상 결과 묶음 추가", AddThermalAsync), ("ThermalLink", "선택 자료를 열화상 묶음에 연결", LinkThermalSelectedAsync), ("ThermalRemove", "선택 열화상 묶음 해제", RemoveThermalAsync) }) AddButton(toolbar, name, label, () => Run(action));
        var tabs = new TabControl { Dock = DockStyle.Fill }; var groups = new TabPage("항목·조건·진단/협의 메모"); groups.Controls.Add(_electricalGrid); var thermal = new TabPage("수정 BMT·최종사진·결과표"); thermal.Controls.Add(_thermalGrid); var result = new TabPage("연결·분석 결과"); result.Controls.Add(_electricalResult); tabs.TabPages.AddRange([groups, thermal, result]); tab.Controls.Add(tabs); tab.Controls.Add(toolbar); _tabs.TabPages.Add(tab);
        foreach (var (name, label, width) in new[] { ("id", "구분", 90), ("title", "진단 항목", 190), ("materialIds", "근거 자료 ID", 180), ("conditions", "측정 지점·기간·조건/누락", 230), ("diagnosis", "검토·진단 메모", 230), ("consultation", "협의 상태", 110), ("agreement", "협의일·참여자·합의 내용", 230) }) _electricalGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = name, HeaderText = label, Width = width, ReadOnly = name is "id" or "title" or "materialIds" });
        foreach (var (name, label, width) in new[] { ("id", "묶음 ID", 100), ("name", "설비·측정 위치", 160), ("bmt", "수정 BMT 자료 ID", 180), ("image", "최종 사진 자료 ID", 180), ("measurements", "대조 엑셀 ID(선택)", 180), ("pointLabels", "탐지점·상 연결", 160) }) _thermalGrid.Columns.Add(new DataGridViewTextBoxColumn { Name = name, HeaderText = label, Width = width, ReadOnly = name == "id" });
        _thermalGrid.Columns.Add(new DataGridViewCheckBoxColumn { Name = "pointsConfirmed", HeaderText = "탐지점 확인" }); _thermalGrid.Columns.Add(new DataGridViewCheckBoxColumn { Name = "imageConfirmed", HeaderText = "사진 배율·위치 확인" });
        _electricalGrid.CellValueChanged += (_, _) => _dirty = true; _thermalGrid.CellValueChanged += (_, _) => _dirty = true; ShowElectricalState();
    }
    private void ResetElectrical() { _electricalState = new JsonObject(); ShowElectricalState(); }
    private void LoadElectrical(JsonNode value) { _electricalState = value["electrical"] as JsonObject ?? new JsonObject(); ShowElectricalState(); }
    private void SaveElectrical(JsonObject value) { ReadElectricalState(); value["electrical"] = _electricalState.DeepClone(); }
    private void ShowElectricalState()
    {
        _electricalScope.Text = _electricalState["scope"]?.ToString() ?? ""; _kepcoMode.SelectedItem = _electricalState["kepcoMode"]?.ToString() ?? "auto"; _kepcoReason.Text = _electricalState["kepcoReason"]?.ToString() ?? ""; _periodStart.Text = _electricalState["periodStart"]?.ToString() ?? ""; _periodEnd.Text = _electricalState["periodEnd"]?.ToString() ?? "";
        _electricalGrid.Rows.Clear(); foreach (var (id, title) in ElectricalGroups) { var notes = _electricalState["notes"]?[id]; var ids = _electricalState["inputs"]?[id]?.AsArray().Select(item => item?["materialId"]?.ToString()) ?? []; _electricalGrid.Rows.Add(id, title, string.Join(";", ids), notes?["conditions"]?.ToString() ?? "", notes?["diagnosis"]?.ToString() ?? "", notes?["consultation"]?.ToString() ?? "proposed", notes?["agreement"]?.ToString() ?? ""); }
        _thermalGrid.Rows.Clear(); foreach (var item in _electricalState["thermalDeliveries"]?.AsArray() ?? []) _thermalGrid.Rows.Add(item!["id"]?.ToString() ?? Guid.NewGuid().ToString("N"), item["name"]?.ToString() ?? "", item["bmt"]?["materialId"]?.ToString() ?? "", item["image"]?["materialId"]?.ToString() ?? "", item["measurements"]?["materialId"]?.ToString() ?? "", item["pointLabels"]?.ToString() ?? "", item["pointsConfirmed"]?.GetValue<bool>() ?? false, item["imageConfirmed"]?.GetValue<bool>() ?? false);
    }
    private void ReadElectricalState()
    {
        _electricalGrid.EndEdit(); _thermalGrid.EndEdit(); _electricalState["scope"] = _electricalScope.Text; _electricalState["kepcoMode"] = _kepcoMode.SelectedItem?.ToString() ?? "auto"; _electricalState["kepcoReason"] = _kepcoReason.Text; _electricalState["periodStart"] = _periodStart.Text; _electricalState["periodEnd"] = _periodEnd.Text;
        foreach (var value in new[] { _periodStart.Text, _periodEnd.Text }) if (value != "" && !DateOnly.TryParseExact(value, "yyyy-MM-dd", out _)) throw new InvalidDataException(); if (_periodStart.Text != "" && _periodEnd.Text != "" && string.CompareOrdinal(_periodStart.Text, _periodEnd.Text) > 0) throw new InvalidDataException();
        var notes = new JsonObject(); foreach (DataGridViewRow row in _electricalGrid.Rows) { string Cell(string key) => Convert.ToString(row.Cells[key].Value) ?? ""; if (Cell("consultation") is not ("proposed" or "discussing" or "agreed")) throw new InvalidDataException(); notes[Cell("id")] = new JsonObject { ["conditions"] = Cell("conditions"), ["diagnosis"] = Cell("diagnosis"), ["consultation"] = Cell("consultation"), ["agreement"] = Cell("agreement") }; }
        _electricalState["notes"] = notes;
        var deliveries = new JsonArray(); foreach (DataGridViewRow row in _thermalGrid.Rows) { string Cell(string key) => Convert.ToString(row.Cells[key].Value) ?? ""; var item = new JsonObject { ["id"] = Cell("id"), ["name"] = Cell("name"), ["pointLabels"] = Cell("pointLabels"), ["pointsConfirmed"] = row.Cells["pointsConfirmed"].Value is true, ["imageConfirmed"] = row.Cells["imageConfirmed"].Value is true }; foreach (var role in new[] { "bmt", "image", "measurements" }) if (Cell(role) != "") { var material = _materials.FirstOrDefault(m => m.Id == Cell(role) && m.Role == "current") ?? throw new InvalidDataException(); item[role] = new JsonObject { ["materialId"] = material.Id, ["sha256"] = material.Sha256, ["filename"] = material.Filename }; } deliveries.Add(item); }
        _electricalState["thermalDeliveries"] = deliveries;
    }
    private async Task SaveElectricalAsync() { ReadElectricalState(); await SaveAsync(Token); Status("전기 범위·조건·협의 메모를 저장했습니다. 담당자 입력 메모이며 자동 측정/판정이 아닙니다."); }
    public async Task LinkElectricalMaterialAsync(string sectionId, string materialId)
    {
        if (!ElectricalGroups.Any(group => group.Id == sectionId)) throw new InvalidDataException(); var material = _materials.FirstOrDefault(item => item.Id == materialId) ?? throw new InvalidDataException(); if (material.Role != "current") throw new InvalidDataException(); ReadElectricalState(); var inputs = _electricalState["inputs"] as JsonObject ?? new JsonObject(); var links = inputs[sectionId] as JsonArray ?? new JsonArray(); if (!links.Any(item => item?["materialId"]?.ToString() == material.Id)) links.Add(new JsonObject { ["materialId"] = material.Id, ["sha256"] = material.Sha256, ["filename"] = material.Filename }); inputs[sectionId] = links.DeepClone(); _electricalState["inputs"] = inputs.DeepClone(); ShowElectricalState(); await InspectElectricalAsync(); await SaveAsync(Token);
    }
    private async Task LinkSelectedElectricalAsync() { if (_electricalGrid.SelectedRows.Count == 0 || _evidence.SelectedItem is not EvidenceItem material) throw new InvalidOperationException(); await LinkElectricalMaterialAsync(Convert.ToString(_electricalGrid.SelectedRows[0].Cells["id"].Value)!, material.Id); }
    private async Task UnlinkElectricalAsync() { if (_electricalGrid.SelectedRows.Count == 0) throw new InvalidOperationException(); ReadElectricalState(); var id = Convert.ToString(_electricalGrid.SelectedRows[0].Cells["id"].Value)!; (_electricalState["inputs"] as JsonObject)?.Remove(id); ShowElectricalState(); await SaveAsync(Token); }
    public async Task InspectElectricalAsync()
    {
        await AuthorizeProfile(true, Token); if (_bundle == null) throw new InvalidOperationException(); ReadElectricalState(); var context = new JsonObject { ["state"] = _electricalState.DeepClone(), ["materials"] = new JsonArray(_materials.Where(item => item.Role == "current").Select(item => (JsonNode)new JsonObject { ["id"] = item.Id, ["sha256"] = item.Sha256, ["filename"] = item.Filename, ["format"] = Path.GetExtension(item.Filename).TrimStart('.').ToLowerInvariant() }).ToArray()), ["deliveries"] = _electricalState["thermalDeliveries"]?.DeepClone() ?? new JsonArray() }; var file = Path.Combine(_projectRoot, "electrical-" + Guid.NewGuid().ToString("N") + ".json"); await Atomic(file, context.ToJsonString(), Token); var result = await Execute(Command("electrical", file)); _electricalResult.Text = "전기 항목·자료 연결 검토 · 실제 판정 아님\n" + result.ToJsonString(DisplayJson); _electricalState["lastSourceSha256"] = _current!.Sha256;
    }
    private async Task AddThermalAsync() { ReadElectricalState(); var items = _electricalState["thermalDeliveries"] as JsonArray ?? new JsonArray(); items.Add(new JsonObject { ["id"] = Guid.NewGuid().ToString("N"), ["name"] = "", ["pointLabels"] = "", ["pointsConfirmed"] = false, ["imageConfirmed"] = false }); _electricalState["thermalDeliveries"] = items.DeepClone(); ShowElectricalState(); await SaveAsync(Token); }
    private async Task LinkThermalSelectedAsync() { if (_thermalGrid.SelectedRows.Count == 0 || _evidence.SelectedItem is not EvidenceItem material) throw new InvalidOperationException(); if (material.Role != "current") throw new InvalidDataException(); var role = Path.GetExtension(material.Filename).ToLowerInvariant() switch { ".bmt" => "bmt", ".xlsx" => "measurements", ".png" or ".jpg" or ".jpeg" or ".webp" => "image", _ => throw new InvalidDataException() }; _thermalGrid.SelectedRows[0].Cells[role].Value = material.Id; _thermalGrid.SelectedRows[0].Cells["pointsConfirmed"].Value = false; _thermalGrid.SelectedRows[0].Cells["imageConfirmed"].Value = false; await SaveElectricalAsync(); }
    private async Task RemoveThermalAsync() { foreach (var row in _thermalGrid.SelectedRows.Cast<DataGridViewRow>().OrderByDescending(row => row.Index).ToArray()) _thermalGrid.Rows.Remove(row); ReadElectricalState(); await SaveAsync(Token); }
}
